/**
 * @method
 * @name LPAD
 * @description LPAD 처리
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.LPAD = function (val) {
    if (val < 10) {
        return "0" + "" + val;
    } else {
        return val;
    }
};

/**
 * @method
 * @name login
 * @description login 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.login = async function () {
    if ($c.str.getByteLength($c.util.getComponent('ipt_integUsrId').getValue().replace(/ /gi, "")) === 0) {
        await $c.win.alert("아이디를 입력하십시오.");
        $c.util.getComponent("ipt_integUsrId").setValue("");
        $c.util.getComponent("ipt_integUsrId").focus();
        return false;
    } else {
        if ($c.str.getByteLength($c.util.getComponent('ipt_encrypPw').getValue().replace(/ /gi, "")) === 0) {
            await $c.win.alert("비밀번호를 입력하십시오.");
            $c.util.getComponent("ipt_encrypPw").setValue("");
            $c.util.getComponent("ipt_encrypPw").focus();
            return false;
        }
    }
    await scwin.tx_fn_login();
};

/**
 * @method
 * @name showMessage
 * @description show Message 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.showMessage = async function () {
    const message = 'null';
    const errCode = (String(((dma_pageContext.get("errorCode") ?? "")) == null ? '' : ((dma_pageContext.get("errorCode") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("errorCode") ?? "")) == null ? '' : ((dma_pageContext.get("errorCode") ?? ""))));
    const failCnt = (String(((dma_pageContext.get("loginFailCnt") ?? "")) == null ? '' : ((dma_pageContext.get("loginFailCnt") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("loginFailCnt") ?? "")) == null ? '' : ((dma_pageContext.get("loginFailCnt") ?? ""))));
    if (errCode === 'ERROR-9207') {
        if (await $c.win.confirm(message)) {
            const r_integ_usr_id = (String(((dma_pageContext.get("ipt_integUsrId") ?? "")) == null ? '' : ((dma_pageContext.get("ipt_integUsrId") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("ipt_integUsrId") ?? "")) == null ? '' : ((dma_pageContext.get("ipt_integUsrId") ?? ""))));
            const r_encryp_pw = (String(((dma_pageContext.get("ipt_encrypPw") ?? "")) == null ? '' : ((dma_pageContext.get("ipt_encrypPw") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("ipt_encrypPw") ?? "")) == null ? '' : ((dma_pageContext.get("ipt_encrypPw") ?? ""))));
            $c.util.getComponent('dma_loginReq').set('reloginYn', "Y");
            $c.util.getComponent("ipt_integUsrId").setValue(r_integ_usr_id);
            $c.util.getComponent("ipt_encrypPw").setValue(r_encryp_pw);
            await scwin.tx_fn_showMessage();
            return;
        }
    } else {
        await $c.win.alert(message);
    }
};

