scwin.getCookie = function (Name) { const v = $c.util.getSessionStorage(Name); return (v === undefined || v === null) ? '' : v; };

/**
 * @method
 * @name precheckBeforeOpenNotice
 * @description precheck Before Open Notice 처리
 * @param {*} fromDate fromDate
 * @param {*} toDate toDate
 * @returns {void}
 * @hidden N
 */
scwin.precheckBeforeOpenNotice = function (fromDate, toDate) {
    const curDate = new Date();
    if (fromDate <= curDate && curDate <= toDate) {
        return true;
    }
    return false;
};

/**
 * @method
 * @name gShowWindow
 * @description g Show Window 처리
 * @param {*} strPageURL strPageURL
 * @param {*} strWindowName strWindowName
 * @param {*} lngWidth lngWidth
 * @param {*} lngHeight lngHeight
 * @param {*} strOptions strOptions
 * @returns {void}
 * @hidden N
 */
scwin.gShowWindow = function (strPageURL, strWindowName, lngWidth, lngHeight, strOptions) {
    let lngTop, lngLeft;
    if (strOptions === "") {
        strOptions = "toolbar=no, location=no, menubar=no, scrollbars=yes, status=yes, resizable=no";
    }
    lngTop = (screen.height - lngHeight) / 2;
    lngLeft = (screen.width - lngWidth) / 2;
    strOptions = strOptions + ", width=" + lngWidth + ", height=" + lngHeight + ", top=" + lngTop + ", left=" + lngLeft;
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    const newWin = $c.win.openPopup((function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(strPageURL), { id: strWindowName }, {});
};

/**
 * @method
 * @name IEVersionCheck
 * @description IEVersion Check 처리
 * @returns {void}
 * @hidden N
 */
scwin.IEVersionCheck = function () {
    let word;
    let version = "N/A";
    const agent = navigator.userAgent.toLowerCase();
    const name = navigator.appName;
    if (name === "Microsoft Internet Explorer") {
        word = "msie ";
    } else {
        if (agent.search("trident") > -1) {
            word = "trident/.*rv:";
        } else {
            if (agent.search("edge/") > -1) {
                word = "edge/";
            }
        }
    }
    const reg = new RegExp(word + "([0-9]{1,})(\\.{0,}[0-9]{0,1})");
    if (reg.exec(agent) != null) {
        version = RegExp.$1 + RegExp.$2;
    }
    return version;
};
